(() => {
  const parse = (v) => {
    const vv = String(v || '');
    if (vv === '' || vv === 'transparent') return null;
    if (!vv.includes('(')) return null;
    const inner = vv.slice(vv.indexOf('(') + 1, vv.indexOf(')'));
    const p = inner.split(/[\s,/]+/).filter((s) => s !== '').map(Number);
    if (p.length < 3 || p.some((n) => Number.isNaN(n))) return null;
    return { r: p[0], g: p[1], b: p[2], a: p.length > 3 ? p[3] : 1 };
  };
  const lum = (c) => {
    const f = (x) => { const s = x / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
    return 0.2126 * f(c.r) + 0.7152 * f(c.g) + 0.0722 * f(c.b);
  };
  const ratio = (a, b) => {
    const x = Math.max(lum(a), lum(b));
    const y = Math.min(lum(a), lum(b));
    return Math.round(((x + 0.05) / (y + 0.05)) * 100) / 100;
  };
  const mix = (fg, bg, alpha) => ({
    r: Math.round(fg.r * alpha + bg.r * (1 - alpha)),
    g: Math.round(fg.g * alpha + bg.g * (1 - alpha)),
    b: Math.round(fg.b * alpha + bg.b * (1 - alpha)),
    a: 1,
  });
  const pageBg = (el) => {
    let n = el.parentElement;
    while (n !== null) {
      const c = parse(getComputedStyle(n).backgroundColor);
      if (c !== null && c.a > 0.99) return c;
      n = n.parentElement;
    }
    return { r: 0, g: 0, b: 0, a: 1 };
  };
  const hostOf = (el) => el.closest('.cm-editor') !== null ? 'edit' : el.closest('.diary-body') !== null ? 'diary' : el.closest('.comment-view') !== null ? 'view' : 'other';
  window.__taskFacts = (selector) => [...document.querySelectorAll(selector)].map((el, i) => {
    const cs = getComputedStyle(el);
    const bg = pageBg(el);
    const border = parse(cs.borderTopColor);
    const fill = parse(cs.backgroundColor);
    const alpha = Number(cs.opacity);
    const borderEff = border === null ? null : mix(border, bg, alpha * border.a);
    const fillEff = fill === null ? null : mix(fill, bg, alpha * fill.a);
    const after = getComputedStyle(el, '::after');
    const rect = el.getBoundingClientRect();
    return {
      i, host: hostOf(el), checked: el.checked,
      appearance: cs.appearance, accent: cs.accentColor, scheme: cs.colorScheme, opacity: alpha,
      border: cs.borderTopColor, fill: cs.backgroundColor,
      bg: 'rgb(' + bg.r + ',' + bg.g + ',' + bg.b + ')',
      contrastBorder: borderEff === null ? null : ratio(borderEff, bg),
      contrastFill: fillEff === null ? null : ratio(fillEff, bg),
      mark: after.maskImage !== 'none' || after.backgroundImage !== 'none',
      size: Math.round(rect.width) + 'x' + Math.round(rect.height),
    };
  });
  window.__taskGate = (selector) => {
    const facts = window.__taskFacts(selector);
    const open = facts.filter((f) => !f.checked);
    const done = facts.filter((f) => f.checked);
    if (open.length === 0) return 'no-unchecked';
    for (const f of open) {
      if (f.opacity < 1) return 'dimmed:' + f.host + ':' + f.opacity;
      if (f.contrastBorder === null || f.contrastBorder < 4.5) return 'border:' + f.host + ':' + f.contrastBorder;
      if (f.size.split('x').some((n) => Number(n) < 10)) return 'size:' + f.size;
    }
    if (done.length === 0) return 'no-checked';
    for (const f of done) {
      if (f.contrastFill === null || f.contrastFill < 3) return 'fill:' + f.host + ':' + f.contrastFill;
      if (!f.mark) return 'no-mark:' + f.host;
    }
    const openFill = open[0].fill;
    if (done[0].fill === openFill) return 'states-indistinct';
    return 'ok';
  };
  window.__dbl = (selector, word) => {
    const el = document.querySelector(selector);
    if (el === null) return 'no-el';
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    let node = walker.nextNode();
    while (node !== null) {
      const text = node.textContent || '';
      const at = text.indexOf(word);
      if (at >= 0) {
        const range = document.createRange();
        range.setStart(node, at);
        range.setEnd(node, at + word.length);
        const selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, clientX: 0, clientY: 0 }));
        el.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, clientX: 0, clientY: 0 }));
        el.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, clientX: 0, clientY: 0 }));
        return 'ok';
      }
      node = walker.nextNode();
    }
    return 'no-word';
  };
  return 'installed';
})()
